package net.officefloor.hq.app.period;

import java.math.BigDecimal;
import java.sql.Date;
import java.time.LocalDate;
import java.util.List;
import org.springframework.dao.DuplicateKeyException;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.stereotype.Repository;

/** The period store: named, non-overlapping date ranges (both ends inclusive), kept per sheet. */
@Repository
public class Periods {

    private static final RowMapper<PeriodResponse> ROW = (rs, i) -> {
        BigDecimal total = rs.getBigDecimal("closed_total");
        return new PeriodResponse(rs.getString("name"), rs.getDate("from_date").toLocalDate().toString(),
                rs.getDate("to_date").toLocalDate().toString(), rs.getBoolean("closed"),
                total == null ? "" : total.setScale(2).toPlainString());
    };

    private final JdbcTemplate jdbc;

    public Periods(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** The sheet's periods, by from-date. */
    public List<PeriodResponse> list(String sheetId) {
        return jdbc.query("SELECT * FROM period WHERE sheet_id = ? ORDER BY from_date", ROW, sheetId);
    }

    /** The named period, its row locked until the transaction ends; null when none. */
    public PeriodResponse lock(String sheetId, String name) {
        List<PeriodResponse> found = jdbc.query("SELECT * FROM period WHERE sheet_id = ? AND name = ? FOR UPDATE",
                ROW, sheetId, name);
        return found.isEmpty() ? null : found.get(0);
    }

    /** Close the named period, fixing its due-total. */
    public void close(String sheetId, String name, BigDecimal total) {
        jdbc.update("UPDATE period SET closed = TRUE, closed_total = ? WHERE sheet_id = ? AND name = ?",
                total, sheetId, name);
    }

    /** Reopen the named period, dropping its fixed due-total. */
    public void reopen(String sheetId, String name) {
        jdbc.update("UPDATE period SET closed = FALSE, closed_total = NULL WHERE sheet_id = ? AND name = ?",
                sheetId, name);
    }

    /** Whether a date falls inside a closed period of the sheet. */
    public boolean isClosed(String sheetId, LocalDate date) {
        Integer closed = jdbc.queryForObject(
                "SELECT COUNT(*) FROM period WHERE sheet_id = ? AND closed AND from_date <= ? AND to_date >= ?",
                Integer.class, sheetId, Date.valueOf(date), Date.valueOf(date));
        return closed != null && closed > 0;
    }

    /** The name of the sheet's period whose dates contain the date; null when none does. */
    public String nameOn(String sheetId, LocalDate date) {
        List<String> found = jdbc.query("SELECT name FROM period WHERE sheet_id = ? AND from_date <= ? AND to_date >= ?",
                (rs, i) -> rs.getString(1), sheetId, Date.valueOf(date), Date.valueOf(date));
        return found.isEmpty() ? null : found.get(0);
    }

    /** Add a period, refusing a name already on the sheet or dates overlapping another period. */
    public void add(String sheetId, ValidPeriod period) throws InvalidPeriodException {
        // Lock the sheet's row so two periods added at once cannot both pass the overlap check.
        jdbc.query("SELECT id FROM sheet WHERE id = ? FOR UPDATE", (rs, i) -> rs.getString(1), sheetId);
        Integer named = jdbc.queryForObject("SELECT COUNT(*) FROM period WHERE sheet_id = ? AND name = ?",
                Integer.class, sheetId, period.name());
        if (named != null && named > 0) {
            throw new InvalidPeriodException("A period named " + period.name() + " is already on the sheet");
        }
        Integer overlapping = jdbc.queryForObject(
                "SELECT COUNT(*) FROM period WHERE sheet_id = ? AND from_date <= ? AND to_date >= ?",
                Integer.class, sheetId, Date.valueOf(period.to()), Date.valueOf(period.from()));
        if (overlapping != null && overlapping > 0) {
            throw new InvalidPeriodException("The period's dates overlap another period");
        }
        try {
            jdbc.update("INSERT INTO period (sheet_id, name, from_date, to_date) VALUES (?, ?, ?, ?)",
                    sheetId, period.name(), Date.valueOf(period.from()), Date.valueOf(period.to()));
        } catch (DuplicateKeyException raced) {
            throw new InvalidPeriodException("A period named " + period.name() + " is already on the sheet");
        }
    }
}
package net.officefloor.hq.app.period;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimResponse;
import net.officefloor.hq.app.claim.Claims;
import net.officefloor.hq.app.claim.LateCharge;
import net.officefloor.hq.app.claim.Rounding;
import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.rate.Rates;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.hq.app.sheet.Sheets;
import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestBody;

/** Closes a period, fixing its due-total as it is now: the dues of the claims that count dated in
 *  it, each with its late charge (a person's unbound OPEN claims dated within one of their holds count in none; a claim whose due is n/a adds nothing). */
public class ClosePeriod {
    public void close(@PathVariable("sheetId") String sheetId, @PathVariable("name") String name,
            @RequestBody ClosePeriodRequest request, Periods periods, People people, Claims claims, Rates rates,
            Settings settings, Sheets sheets, Audit audit, ObjectResponse<List<PeriodResponse>> response) throws InvalidPeriodException {
        PeriodResponse period = periods.lock(sheetId, name);
        if (period == null) {
            throw new InvalidPeriodException("No period named " + name + " is on the sheet");
        }
        if (period.closed()) {
            throw new InvalidPeriodException("The period " + name + " is already closed");
        }
        LocalDate from = LocalDate.parse(period.from());
        LocalDate to = LocalDate.parse(period.to());
        BigDecimal total = BigDecimal.ZERO.setScale(2);
        BigDecimal floor = settings.floor(sheetId);
        BigDecimal latePct = settings.latePct(sheetId);
        LocalDate policyDate = settings.policyDate(sheetId);
        LocalDate today = sheets.today(sheetId);
        List<Claim> all = claims.list(sheetId);
        for (Person person : people.list(sheetId)) {
            for (Claim claim : all) {
                if (claim.getPersonId() != person.getId() || !person.countsLive(claim)
                        || claim.getDate().isBefore(from) || claim.getDate().isAfter(to)) {
                    continue;
                }
                RoundingMode rounding = Rounding.of(claim, policyDate);
                BigDecimal fixed = ClaimResponse.fixedDue(claim);
                BigDecimal figure = fixed != null || claim.isBound() ? fixed
                        : Rates.due(claim.getAmount(), rates.find(sheetId, person.gradeOn(claim.getDate()), claim.getDate()), floor, rounding);
                if (figure != null) {
                    total = total.add(LateCharge.withCharge(claim, figure, latePct, today, rounding));
                }
            }
        }
        periods.close(sheetId, name, total);
        audit.recordOnCommit("PERIOD_CLOSED sheet=" + sheetId + " by=" + request.user()
                + " period=" + name + " total=" + total.toPlainString());
        response.send(periods.list(sheetId));
    }
}
package net.officefloor.hq.app.period;

import java.util.List;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestBody;

/** Reopens a closed period, by a steward only: its fixed due-total is dropped, so it totals its
 *  claims' current figures again. */
public class ReopenPeriod {
    public void reopen(@PathVariable("sheetId") String sheetId, @PathVariable("name") String name,
            @RequestBody ClosePeriodRequest request, Periods periods, Settings settings, Audit audit,
            ObjectResponse<List<PeriodResponse>> response) throws InvalidPeriodException {
        if (!Settings.STEWARD.equals(settings.role(sheetId, request.user()))) {
            throw new InvalidPeriodException("Only a steward can reopen a period");
        }
        PeriodResponse period = periods.lock(sheetId, name);
        if (period == null) {
            throw new InvalidPeriodException("No period named " + name + " is on the sheet");
        }
        if (!period.closed()) {
            throw new InvalidPeriodException("The period " + name + " is not closed");
        }
        periods.reopen(sheetId, name);
        audit.recordOnCommit("PERIOD_REOPENED sheet=" + sheetId + " by=" + request.user() + " period=" + name);
        response.send(periods.list(sheetId));
    }
}
package net.officefloor.hq.app.period;

/** Body of POST /api/sheets/{sheetId}/periods/{name}/close (or /reopen): the user closing or reopening it. */
public record ClosePeriodRequest(String user) {
}
package net.officefloor.hq.app.period;

/** A period: its name and its from and to dates (YYYY-MM-DD, both inclusive); whether it is closed,
 *  and the due-total fixed when it was closed ("" while open). */
public record PeriodResponse(String name, String from, String to, boolean closed, String closedTotal) {
}
package net.officefloor.hq.app.period;

import java.util.List;
import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.PathVariable;

public class LoadPeriods {
    public void service(@PathVariable("sheetId") String sheetId, Periods periods,
            ObjectResponse<List<PeriodResponse>> response) {
        response.send(periods.list(sheetId));
    }
}
