-- A sheet's periods: a name unique on the sheet and a from and to date, both inclusive. No two
-- periods on a sheet overlap, so a claim belongs to the one period whose dates contain its date,
-- or to none.
CREATE TABLE period (
    sheet_id  VARCHAR(200) NOT NULL,
    name      VARCHAR(200) NOT NULL,
    from_date DATE         NOT NULL,
    to_date   DATE         NOT NULL,
    PRIMARY KEY (sheet_id, name)
);
-- A period can be closed: closed_total is its due-total fixed at that moment, kept whatever the
-- rates do later. No claim dated inside a closed period can be added, edited or change status.
ALTER TABLE period ADD COLUMN closed BOOLEAN DEFAULT FALSE NOT NULL;
ALTER TABLE period ADD COLUMN closed_total DECIMAL(14,2);
-- Period numbering: from period_numbering_from (NULL: off), a claim opened on or after it is numbered
-- within its period (<period>-<n>, or X-<n> for a claim in no period). A claim's number, and the
-- number a correction names, are therefore text; earlier claims keep their sheet-wide numbers.
ALTER TABLE sheet ADD COLUMN period_numbering_from DATE;
ALTER TABLE claim ALTER COLUMN claim_number SET DATA TYPE VARCHAR(220);
ALTER TABLE claim ALTER COLUMN corrects SET DATA TYPE VARCHAR(220);
-- The last number given in each period's sequence; period_name '' is the sequence of claims in no period.
CREATE TABLE period_claim_number (
    sheet_id    VARCHAR(200) NOT NULL,
    period_name VARCHAR(200) NOT NULL,
    last_number BIGINT       NOT NULL,
    PRIMARY KEY (sheet_id, period_name)
);
import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { asString, useSearchParam } from '../../url/useSearchParam';
import { useSubmitOnce } from '../../query/useSubmitOnce';
import { formatCents } from '../rates/due';
import { usePeriodDueTotal } from './usePeriodDueTotal';
import { periodsKey, usePeriods, type Period } from './usePeriods';

// The sheet's periods, each with its dates and due-total (the dues, late charges included, of the claims that count whose
// date falls in it, leaving out a held person's OPEN claims; a claim whose due is n/a adds nothing), and the form that adds one (a name not
// already on the sheet, a from-date on or before the to-date, not overlapping another period). A
// closed period shows the due-total fixed when it was closed, whatever the rates do later; a steward
// can reopen it, making its due-total live again.
export function PeriodPanel() {
  const [sheet] = useSearchParam('sheet', asString);
  const [user] = useSearchParam('user', asString);
  const periods = usePeriods(sheet);
  const dueTotalOf = usePeriodDueTotal(sheet);
  const [name, setName] = useState('');
  const [from, setFrom] = useState('');
  const [to, setTo] = useState('');
  const queryClient = useQueryClient();
  const submitOnce = useSubmitOnce();
  const add = useMutation({
    mutationFn: (body: { name: string; from: string; to: string }) =>
      postJson<Period[]>(`/api/sheets/${encodeURIComponent(sheet)}/periods`, { ...body, user }),
    onSuccess: (saved) => {
      setName('');
      setFrom('');
      setTo('');
      queryClient.setQueryData(periodsKey(sheet), saved);
    },
  });
  // Close a period, or reopen a closed one (a steward only).
  const act = useMutation({
    mutationFn: ({ name, action }: { name: string; action: 'close' | 'reopen' }) =>
      postJson<Period[]>(
        `/api/sheets/${encodeURIComponent(sheet)}/periods/${encodeURIComponent(name)}/${action}`,
        { user },
      ),
    onSuccess: (saved) => queryClient.setQueryData(periodsKey(sheet), saved),
  });
  return (
    <>
      <table data-testid="periods">
        <thead>
          <tr>
            <th>Period</th>
            <th>From</th>
            <th>To</th>
            <th>Due</th>
            <th>Closed</th>
            <th></th>
          </tr>
        </thead>
        <tbody>
          {periods.map((p) => (
            <tr key={p.name} data-testid={`period-row-${p.name}`}>
              <td data-testid="period-name">{p.name}</td>
              <td data-testid="period-from">{p.from}</td>
              <td data-testid="period-to">{p.to}</td>
              <td data-testid="period-due-total">{formatCents(dueTotalOf(p))}</td>
              <td data-testid="period-closed">{p.closed ? 'yes' : 'no'}</td>
              <td>
                {!p.closed && (
                  <button
                    type="button"
                    data-testid="period-close"
                    onClick={() => {
                      act.reset();
                      act.mutate({ name: p.name, action: 'close' });
                    }}
                  >
                    Close
                  </button>
                )}{' '}
                <button
                  type="button"
                  data-testid="period-reopen"
                  onClick={() => {
                    act.reset();
                    act.mutate({ name: p.name, action: 'reopen' });
                  }}
                >
                  Reopen
                </button>
                {act.isError && act.variables?.name === p.name && (
                  <span data-testid="period-error" role="alert">
                    {act.variables.action === 'reopen'
                      ? ' Could not reopen the period: only a steward can reopen it, and only while it is closed.'
                      : ' Could not close the period.'}
                  </span>
                )}
              </td>
            </tr>
          ))}
        </tbody>
      </table>
      <form
        data-testid="period-form"
        onSubmit={(e) => {
          e.preventDefault();
          submitOnce(() => {
            add.reset();
            return add.mutateAsync({ name: name.trim(), from: from.trim(), to: to.trim() });
          });
        }}
      >
        <input
          data-testid="period-form-name"
          value={name}
          placeholder="Period name"
          onChange={(e) => {
            setName(e.target.value);
            add.reset();
          }}
        />{' '}
        <input
          data-testid="period-form-from"
          value={from}
          placeholder="From (YYYY-MM-DD)"
          onChange={(e) => {
            setFrom(e.target.value);
            add.reset();
          }}
        />{' '}
        <input
          data-testid="period-form-to"
          value={to}
          placeholder="To (YYYY-MM-DD)"
          onChange={(e) => {
            setTo(e.target.value);
            add.reset();
          }}
        />{' '}
        <button type="submit" data-testid="period-form-submit">Add period</button>
        {add.isError && <span data-testid="period-form-error" role="alert"> Could not add the period: it needs a name not already on the sheet and a from-date on or before its to-date (YYYY-MM-DD), not overlapping another period.</span>}
      </form>
    </>
  );
}
import { countsLive, useClaims } from '../claims/useClaims';
import { gradeOn, heldOn, usePeople } from '../people/usePeople';
import { claimDue, toCents } from '../rates/due';
import { rateOn, useRates } from '../rates/useRates';
import { useFloor, useLatePct, usePolicyDate } from '../settings/useSettings';
import { useSheetToday } from '../sheet/useSheetToday';
import { periodOf, usePeriods, type Period } from './usePeriods';

/** A period's due-total: the dues, late charges included, of the claims that count whose date falls
 *  in it, leaving out a person's unbound OPEN claims dated within one of their holds (a claim whose due is n/a adds nothing); a closed
 *  period gives the due-total fixed when it was closed. */
export function usePeriodDueTotal(sheet: string): (period: Period) => bigint {
  const periods = usePeriods(sheet);
  const people = usePeople(sheet);
  const claims = useClaims(sheet);
  const rates = useRates(sheet);
  const floor = useFloor(sheet);
  const late = { pct: useLatePct(sheet), today: useSheetToday(sheet) };
  const policy = usePolicyDate(sheet);
  const personOf = new Map(people.map((p) => [p.id, p]));
  return (period: Period) =>
    period.closed ? toCents(period.closedTotal) : claims
      .filter((c) => personOf.has(c.personId) && countsLive(c, (date) => heldOn(personOf.get(c.personId)!, date)) && periodOf(periods, c.date)?.name === period.name)
      .reduce((sum, c) => sum + (claimDue(c, rateOn(rates, gradeOn(personOf.get(c.personId)!, c.date), c.date), floor, late, policy) ?? 0n), 0n);
}
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';

/** A period: a name unique on the sheet, from and to dates (YYYY-MM-DD, both inclusive), whether it
 *  is closed, and the due-total fixed when it was closed ("" while open). */
export type Period = { name: string; from: string; to: string; closed: boolean; closedTotal: string };

export const periodsKey = (sheet: string) => ['sheet', sheet, 'periods'] as const;

/** The sheet's periods, by from-date. */
export function usePeriods(sheet: string): Period[] {
  const { data } = useQuery({
    queryKey: periodsKey(sheet),
    queryFn: () => getJson<Period[]>(`/api/sheets/${encodeURIComponent(sheet)}/periods`),
    enabled: sheet !== '',
  });
  return data ?? [];
}

/** The period whose dates contain a date; periods never overlap, so there is at most one. */
export function periodOf(periods: Period[], date: string): Period | undefined {
  return periods.find((p) => p.from <= date && date <= p.to);
}

